-- Fictional profiles for the presentation environment. Safe to apply repeatedly.
BEGIN;

UPDATE categories SET name = 'Уборка и клининг', updated_at = now()
WHERE name = 'Клининг (демо)'
  AND NOT EXISTS (SELECT FROM categories WHERE name = 'Уборка и клининг');

ON CONFLICT (name) DO NOTHING;

-- Consolidate only the old active showcase category if its replacement already existed.
UPDATE services SET category_id = (SELECT id FROM categories WHERE name = 'Уборка и клининг')
WHERE category_id IN (SELECT id FROM categories WHERE name = 'Клининг (демо)' AND is_active);
UPDATE categories SET is_active = false, updated_at = now() WHERE name = 'Клининг (демо)';

CREATE TEMP TABLE zrobim_showcase_people (
  user_id uuid, email text, first_name text, last_name text, city text, category text,
  description text, price_one numeric, price_two numeric
) ON COMMIT DROP;


SELECT user_id, email, 'Ag==', 'MASTER', first_name, last_name FROM zrobim_showcase_people
ON CONFLICT DO NOTHING;

UPDATE users SET last_name = 'Соколова', updated_at = now()
WHERE id = 'c8140b79-0b31-4888-a849-57b68d6f8a31' AND last_name = 'Демо';

SELECT p.user_id, p.description, p.city, 'APPROVED'
FROM zrobim_showcase_people p JOIN users u ON u.id = p.user_id AND u.email = p.email AND u.role = 'MASTER'
ON CONFLICT (user_id) DO NOTHING;

UPDATE masters SET description = 'Порядок дома без лишних хлопот. Привезу необходимые средства и инвентарь.', updated_at = now()
WHERE user_id = 'c8140b79-0b31-4888-a849-57b68d6f8a31'
  AND description = 'Демонстрационный профиль для проверки каталога.';

CREATE TEMP TABLE zrobim_showcase_services (
  category text, name_one text, name_two text, duration_one integer, duration_two integer,
  location location_type, description_one text, description_two text
) ON COMMIT DROP;

SELECT CASE
    WHEN p.user_id = 'c8140b79-0b31-4888-a849-57b68d6f8a31' AND variant.n = 1 THEN 'b6242cef-109c-4f2a-b865-69ef262384a2'::uuid
    WHEN p.user_id = 'c8140b79-0b31-4888-a849-57b68d6f8a31' AND variant.n = 2 THEN 'f6e4f9e1-55d8-47b9-9082-206e665856c8'::uuid
    ELSE md5(p.user_id::text || ':service:' || variant.n::text)::uuid
  END,
  m.id, c.id,
  CASE WHEN variant.n = 1 THEN d.name_one ELSE d.name_two END,
  CASE WHEN variant.n = 1 THEN d.description_one ELSE d.description_two END,
  CASE WHEN variant.n = 1 THEN p.price_one ELSE p.price_two END,
  CASE WHEN variant.n = 1 THEN d.duration_one ELSE d.duration_two END,
  d.location
FROM zrobim_showcase_people p
JOIN users u ON u.id = p.user_id AND u.email = p.email AND u.role = 'MASTER'
JOIN masters m ON m.user_id = p.user_id
JOIN categories c ON c.name = p.category
JOIN zrobim_showcase_services d ON d.category = p.category
CROSS JOIN (VALUES (1), (2)) AS variant(n)
ON CONFLICT (id) DO NOTHING;

SELECT m.id, day, '09:00', '18:00'
FROM masters m JOIN zrobim_showcase_people p ON p.user_id = m.user_id
CROSS JOIN generate_series(1, 6) AS day
ON CONFLICT (master_id, day_of_week) DO NOTHING;

COMMIT;
